M(gcf, r"""
public static synchronized String migrateSig56() {
  java.nio.file.Path f = FILE;
  if (f == null || Boolean.getBoolean("skyy.harness.nosig56")) return "";
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = s56Update(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    lvKit(f.toAbsolutePath().getParent());
    @PKG@.CfgHist.snapshot(0, old, @PKG@.CfgHist.stamp(), H56_WHO, "before the 0.3.56 signature defaults update");
    if (!lvSaved(old)) {
      @PKG@.Gear.warn("config.properties NOT updated with the 0.3.56 signature defaults: the old file could not be kept in " + @PKG@.CfgHist.DIR + " (The Paperweight / the Ricochet bow charge normally until then; the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    String[] rows = (String[]) r[3];
    for (int i = 0; i + 1 < rows.length; i += 2) @PKG@.CfgLog.enqueue(s56Log(rows[i], rows[i + 1]));
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String[] notes = (String[]) r[1];
    String add = (String) r[2];
    String msg = "config.properties: the 0.3.56 signature defaults were added at the end (" + (rows.length / 2) + " lines" + (add.length() > 0 ? ": " + add : " - only the marker, every line was there") + "; Undo in Server Setup's change log); no value changed; the old file is kept in config-history";
    @PKG@.Gear.info(msg);
    StringBuilder all = new StringBuilder(msg);
    for (int i = 0; i < notes.length; i++) { @PKG@.Gear.info(notes[i]); all.append('\\n').append(notes[i]); }
    @PKG@.GearLog.line("CONFIG 0.3.56 signature defaults (sig3b): added " + (rows.length / 2) + " lines" + (add.length() > 0 ? "" : " (the marker only)") + (notes.length > 0 ? "; " + notes.length + " notes" : ""));
    return all.toString();
  } catch (Throwable t) {
    @PKG@.Gear.warn("could not add the 0.3.56 signature defaults to config.properties (the file is used as it is): " + t);
    return "";
  }
}""")
